def transform(grid):
    """Recolor complete separator lines to 2."""
    out = [row[:] for row in grid]
    if not out:
        return out
    h, w = len(out), len(out[0])
    # A line is a separator when every cell has the same color.
    # In the demonstrations, complete rows/columns of 0 are marked as 2.
    for r in range(h):
        if len(set(out[r])) == 1:
            out[r] = [2] * w
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            for r in range(h):
                out[r][c] = 2
    return out
